                _sortDirection = next;
                return true;
            }
            case 10:
            {
                var next = value.Boolean;
                if (Equals(_isLoading, next)) return false;
                _isLoading = next;
                return true;
            }
            case 11:
            {
                var next = value.Boolean;
                if (Equals(_canExtractSelected, next)) return false;
                _canExtractSelected = next;
                return true;
            }
            case 12:
            {
                var next = value.Boolean;
                if (Equals(_canExtractAll, next)) return false;
                _canExtractAll = next;
