                _selectedCountLabel = next;
                return true;
            }
            case 14:
            {
                var next = value.Text ?? "";
                if (Equals(_currentPath, next)) return false;
                _currentPath = next;
                return true;
            }
            case 15:
            {
                var next = value.Boolean;
                if (Equals(_canGoUp, next)) return false;
                _canGoUp = next;
                return true;
            }
            case 16:
            {
                var next = value.Text ?? "";
